def offs(demo_in, demo_out):
    rows=[i for i in range(len(demo_in)) if 5 in demo_in[i]]; cols=[j for j in range(len(demo_in[0])) if any(demo_in[i][j]==5 for i in range(len(demo_in)))]
    r0,c0=min(rows),min(cols); n=max(rows)-r0+1
    seen={}
    for i in range(r0,r0+n):
        for j in range(c0,c0+n):
            k=min(i-r0,j-r0,n-1-(i-r0),n-1-(j-r0))
            seen.setdefault(k,set()).add(demo_out[i][j])
    return n,{k:sorted(v) for k,v in sorted(seen.items())}
